scripts.小雷.txt:
//小雷

	If ($Xiaolei == 0) @Xiaolei0;
	If ($Xiaolei == 1) @Xiaolei1;

@Xiaolei0:
	FadeOut();
	ClearBody();
	SaveNpc();
	SaveObj();
	LoadMap("map034_海边小树林.map");
	LoadNpc("map034.npc");
	LoadObj("map034.obj");
	LoadObj(); //坟堆
	SetPlayerPos(*, *);
	SetPlayerDir(*);
	SetNpcPos("小雷",*,*);	
	SetNpcDir("小雷",*);
	SetNpcPos("张琳心",*,*);	
	SetNpcDir("张琳心",*);
	FadeIn();
	Say("小雷：张姑娘，我小叫化不懂什么。但我晓得，人活一辈子，总逃不过个死字，求的——不过是个心安理得。张大侠临死时，总算是了结了一辈子的愧疚，对他未尝不是件好事。姑娘应该为张大侠高兴才是。", 69);
	Say("独孤剑：是啊，琳心。我们要替世伯完成遗志，助岳元帅光复河山，让他老人家死得瞑目。", 1);
	Say("张琳心：爹……琳心和哥哥一定不会辜负你的希望。", 24);
	Goto @End;

@Xiaolei1:
	FadeOut();
	ClearBody();
	SaveNpc();
	SaveObj();
	LoadMap("map034_海边小树林.map");
	LoadNpc("map034.npc");
	LoadObj("map034.obj");
	LoadObj(); //坟堆
	SetPlayerPos(*, *);
	SetPlayerDir(*);
	SetNpcPos("张琳心",*,*);	
	SetNpcDir("张琳心",*);
	FadeIn();
	Say("独孤剑：世伯，你放心！剑儿一定谨记你的遗志，赴汤蹈火，在所不辞。", 1);
	Say("张琳心：爹，我会将真相告诉哥哥，他一定会谅解爹您的。女儿就此拜别了！", 26);
	Say("独孤剑：琳心，我们走吧！……什么人！", 1);
	NpcSpecialAction();//小雷飞身下来，出现在坐标(*,*)上
	Say("小雷：原来飞仙两剑客之间还有这么一段故事！两位前辈简直就是大英雄，大豪杰，好朋友，真朋友，生死朋友！一个想朋友杀，一个要杀朋友，天底下的义气还有比这更义气的吗？小叫化就佩服这样的英雄豪杰。", 69);
	Say("独孤剑：是你？你都看到了。", 8);
	Say("小雷：可惜只看到一点，已经够了。只是有一个问题小叫化一直在想，柳中原都知道张姑娘的爹爹不是真心投靠金人，为何你的师傅却不知道？", 69);
	Say("独孤剑：这……想必是张世伯不想引起金人的怀疑，故而将此事隐瞒得很紧吧。", 1);
	Say("小雷：哈哈，张姑娘的爹爹张大人和令尊是生死之交，令尊连儿子都放心交给你师傅照管，张大人难道还有信不过你师傅的理由？", 69);
	Say("独孤剑：这个……在下委实不知其中的缘由，这么多年来家师也的确不明白张世伯的想法。", 8);
	Say("小雷：其实原因很简单……", 69);
	Say("独孤剑：请教！", 2);
	Say("小雷：就是策划搞昏了头！", 69);
	Goto @End;

@End:
	SetNpcKind("小雷", 3);
	PlayerGotoDir(6,5);
	Say("独孤剑：那我们先去找段姑娘，再麻烦老王，送我们去长安一趟。", 1);
	Say("小雷：反正我在临安也呆不住了，我跟你们一起吧。", 69);
	Say("独孤剑：这个……好吧！", 1);
	SetMaptrap(02,"trap02.txt");
	Assign($Event, 270);
	Return;

scripts.小雷对话.txt:
// 与小雷的同伴对话

	If ($Event == 270) @Event270;
	Return;

@Event270:
	Say("小雷：飞、仙两剑客的故事真是让人感叹哪！我小雷什么时候能够找到一个生死相知的朋友，也就死而无憾了！", 69);
	Return;

scripts.张琳心对话.txt:
// 与张琳心的同伴对话

	If ($Event == 260) @Event260;
	If ($Event == 270) @Event270;
	
	Return;


@Event260:
	Say("张琳心：这一走，不知何时才能回家……", 28);
	Say("独孤剑：张姑娘，别难过了，你爹既然是被冤屈的，总会有平反昭雪的一天，那时你就可以回家啦。", 1);
	Return;

@Event270:
	Say("张琳心：我一定要杀了南宫灭，给爹报仇！", 26);
	Say("独孤剑：琳儿，这个仇我们一起来报，你不要太伤心了。", 1);
	Return;

scripts.打败南宫灭.txt:
// 打败南宫灭，面对濒死的张风，独孤剑面临选择

	//打败南宫灭
	

	AddExp(2200);	

	FadeOut();
	StopMusic();
	SetPlayerState(0);
	SetNpcRelation("张琳心", 2);
	Say("南宫灭：两个小鬼给我记着，今天你们乘人之危，下次撞到老夫手里，老夫一定剥了你们的皮！", 46);
	ClearBody();
	DelNpc("南宫灭");
	DelNpc("张风");
	SaveNpc();
	AddNpc("npc009_垂死张风.ini", 5, 6, 1);
	SetNpcKind("张琳心", 1);   //取消同伴
	SetPlayerPos(7, 6);
	SetPlayerDir(5);
	SetNpcPos("张琳心", 4, 7);
	SetNpcDir("张琳心", 5);
	SetNpcActionFile("张琳心", 0, "mpc015_2.asf");  //跪下
	SetNpcActionFile("张琳心", 1, "mpc015_2.asf");
	NpcSpecialAction("张琳心", "mpc015_1.asf");
	Sleep(500);
	PlayMusic("满江红.mp3");
	Sleep(500);
	ClearEffect();
	FadeIn();

	//张风垂死
	
	Say("张琳心：爹！……", 26);
	Say("张风：琳儿，不必伤心，为父早已将生死看得淡了。南宫灭武功深不可测，我拼尽全力，本想和他同归于尽，不料……看来，中原武林已无人是他的敌手了。", 45);
	Say("张琳心：爹，你不要……", 26);
	Say("张风：琳儿，你和梦儿都任性惯了，这都怪我平日疏于管教。呵呵……恐怕在九泉之下见到你们的娘，她又要埋怨我了……", 45);
	Say("张风：……今后你们兄妹要互相照顾、相依为命……", 45);
	Say("张琳心：爹……我和哥哥以后都会好好听你的话，我去叫哥哥回来，今后我们一定乖乖地陪在爹身边……听爹的话。", 26);
	Say("张风：傻丫头……咳咳……", 45);
	Say("张风：琳儿，为父知道你的心事，今日为父就将过往的种种孽债一并作个了结。", 45);	
	Say("张风：独孤少侠，你过来，老夫有话与你说……", 45);
	
	PlayerGoto(5, 7);
	SetPlayerDir(3);
	Say("独孤剑：你……", 1);
	Say("张风：独孤少侠，令尊乃是老夫亲手所杀，独孤公子要报父仇，就请现在动手吧。再晚，恐怕……咳咳，恐怕我撑不过了。", 45);
	Say("张琳心（肝肠寸断）：爹……独孤大哥……", 26);
	Say("独孤剑（心乱如麻）：我……我亲手杀死他……", 6);	
	
	//选择杀不杀张风
	
	Choose("杀不杀张风", "A 杀", "B 不杀", $killzhang);
	If ($killzhang == 0) @Choose0;
	If ($killzhang == 1) @Choose1;

@Choose0:
	Say("独孤剑：好！我今天就把国仇家恨和你一起算清！", 5);
	SetNpcActionFile("独孤剑", 0, "mpc016_2.asf");  	//举起剑
	SetNpcActionFile("独孤剑", 1, "mpc016_2.asf");
	NpcSpecialAction("独孤剑", "mpc016_1.asf");
	Sleep(1000);
	Say("张琳心：独孤大哥，不要啊……", 26);
	SetNpcActionFile("张琳心", 0, "npc004_st.asf");  	//站立
	SetNpcActionFile("张琳心", 1, "npc004_pst.asf");
	NpcSpecialAction("张琳心", "mpc015_3.asf");
	Sleep(1000);
	NpcGoto("张琳心", 5, 8);
	SetNpcDir("张琳心", 5);
	Say("张琳心：不要！……", 26);
	Say("独孤剑：……", 6);
	Sleep(1000);
	Say("张琳心：无论如何，你应该给我爹一个解释的机会，难道，你不想知道当年到底发生了事情吗？", 28);
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");  	//放下剑
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	NpcSpecialAction("独孤剑", "mpc016_3.asf");
	Sleep(1000);	
	Say("独孤剑：好，你说，我倒想听听当年你是如何背信弃义，出卖我爹的！", 9);
	Say("张琳心：独孤大哥……", 26);
	Sleep(500);
	Say("张风：看来，我也无需隐瞒什么了。今天，咳咳……", 45);
	PlaySound("特_咳嗽.wav");
	Say("张风：我就将当年的情形原原本本告诉你们，是非恩怨终究得有个了断，否则我死不瞑目。", 45);
	SetPlayerDir(3);
	SetNpcDir("张琳心", 4);
	Sleep(500);
	Say("张风：十二年前，即靖康二年，金军攻破都城开封，不仅将城内金银财宝洗劫一空，还将我大宋的徽、钦两位皇帝也掳去，拘禁在金国的五国城。想我堂堂大宋，居然连皇帝都被掳走，此乃千古奇耻。", 45);	
	Say("张风：我和你父亲还有柳中原约定前去金国救出二帝，由我和你父亲出手营救，柳中原负责接应。没想到金国早料到会有中原的江湖豪杰前往营救，因此早有防备，南宫灭收买了不少武林高手埋伏在四周，我和你父亲无从下手。", 45);
	Say("张风：一天晚上，我俩前去金营打探消息，在金军头领粘罕帐意外发现一个汉人秀才正在向金国献一幅宝图，此图叫做“山河社稷图”，上面标有我大宋江山各处关隘和路径，是一幅绝好的军事地图。金国如果拥有了这幅图，再要南侵就易如反掌了。于是我和你父亲改变了主意，决定夺走这幅图。", 45);
	Say("张风：当晚我们就动了手，图是抢到手了，但遭到了大批武士和金兵的截杀。你父亲要我带图先走，他在后面断后，结果你父亲受伤被俘。", 45);
	Say("张风：第二天我藏好了宝图去救你父亲，不巧又被发现了。眼看难以脱身，我便谎称是来投奔金国的。南宫灭将我带到金国四太子金兀术跟前，那金兀术为了验证我是否真心，竟然要我亲手杀掉你父亲。", 45);
	Say("独孤剑：……", 6);
	Say("张风：此时，南宫灭已经挑断了你父亲双手和双脚的筋络，你父亲受尽折磨，生不如死，见我前来，已知我意，便仰天长笑，并出言激我动手。我和令尊多年挚友，心意相通，看你父亲已抱定舍身取义之志，我便出手给了你父亲一个痛快的了断。", 45);
	Say("张风：此举消除了金兀术对我的怀疑，但南宫灭依然怀疑我和宝图有关。幸好此时柳中原赶到，在城内到处制造混乱，南宫灭才放松了对我的警惕。柳中原将宝图带回了中原，放在武夷山保管了这许多年。", 45);
	Say("张风：我投靠金国的事金国严守秘密，原来他们早有打算，要派一些汉人回来，进入朝廷做官，为日后金军南下作内应。时隔不久，兀术召我见他，说宋朝状元秦桧脱逃，要我一路追上他，但不仅不能杀他，还要护送他平安到达临安。我赶上了秦桧，一路上大家心照不宣。皇上昏庸，秦桧不久就做上了左相和太师，并提拔我做了殿前禁军的头领。我表面上应承秦桧，但背底下破坏了不少他出卖我朝的计划。此贼后来终于怀疑我了，让南宫灭重新调查我，结果被他们打探到了是我盗走了“山河社稷图”。", 45);
	Say("张风：于是秦贼便想将我除去，并找回那幅宝图。那吕文才是秦贼的心腹，昨天带人来我家中搜查，没找到宝图，所以南宫灭就亲自出马了。", 45);
	Say("独孤剑：前辈！你为何不早将其中原委说出来呢？", 6);
	Say("张风：一是事关机密；二是，这些年来我忍辱偷生，又对令尊的死一直耿耿于怀，日夜只受煎熬，但盼……咳咳……早日了结。", 45);
	Say("张琳心：爹……那，那宝图他们拿到没有。", 24);
	Say("张风：这些年……那宝图一直由柳中原保管，眼看，眼看岳元帅不日就可直捣黄龙，我们……我们准备将宝图交给岳元帅……收复失地，重整河山。柳中原……将图带下山来……我在客栈看到暗杀名单，就、就去通知柳中原，等我回来时……那，那宝图已经不见了……", 45);
	Say("张风：咳咳咳咳……", 45);
	PlaySound("特_咳嗽.wav");
	Say("独孤剑：世伯，我对不起你，我一直误解你，怀疑你，差点还杀了你，我……我真是糊涂！", 7);
	Say("张风：这……也怨不得你，咳咳……", 45);
	Say("独孤剑：世伯，你不要说话了，我运气给你疗伤。", 1);
	Say("张风：不必了，我……已……盏枯油尽了。", 45);
	Say("张琳心：爹……呜呜呜……", 26);
	Say("张风：贤侄，我……我想请你好好照顾琳儿……带她找到她哥……你能办到……", 45);
	Say("独孤剑：世伯的嘱托，剑儿一定做到！", 1);
	Say("张风：还有，找……找到图，给……给岳元帅。", 45);
	Say("独孤剑：剑儿谨记！", 1);
	Say("张风：好，好！踏破燕骑，直捣黄龙，哈哈哈哈——", 45);
	
	//张风死掉
	
	SetNpcActionFile("张风", 0, "mpc014_3.asf");  
	SetNpcActionFile("张风", 1, "mpc014_3.asf");
	NpcSpecialAction("张风", "mpc014_2.asf");
	Sleep(1500);
	DelNpc("张风"); 	//对存盘的处理
	AddNpc("npc009_死亡张风.ini", 5, 6, 7);
	SaveNpc();
	
	NpcGoto("张琳心", 4, 7);
	SetNpcDir("张琳心", 5);
	Say("张琳心：爹——", 26);
	SetNpcActionFile("张琳心", 0, "mpc405_2.asf");  	//扑过去
	SetNpcActionFile("张琳心", 1, "mpc405_2.asf");
	NpcSpecialAction("张琳心", "mpc405_1.asf");
	Sleep(1000);
	Say("张琳心：爹……你不要死呀，你不要丢下琳儿啊……呜呜……", 26);
	Sleep(3000);
	PlayerGoto(5, 8);
	SetPlayerDir(3);
	Say("独孤剑：琳儿，人死不能复生，你不要太伤心了……", 7);
	Sleep(1000);
	SetNpcActionFile("张琳心", 0, "npc004_st.asf");  	//站立
	SetNpcActionFile("张琳心", 1, "npc004_pst.asf");
	NpcSpecialAction("张琳心", "mpc405_3.asf");
	Sleep(1000);
	SetNpcDir("张琳心", 7);
	Say("张琳心：独孤哥哥！", 26);
	
	ShowNpc("张琳心", 0);
	SetNpcActionFile("独孤剑", 0, "mpc406a_2.asf");
	SetNpcActionFile("独孤剑", 1, "mpc406a_2.asf");
	NpcSpecialAction("独孤剑", "mpc406a_1.asf");
	Sleep(2500);
	Say("张琳心：独孤哥哥……呜呜……", 26);
	Say("独孤剑：别哭了，琳儿。", 1);
	Say("独孤剑：琳儿，我答应过你爹要好好照顾你，我一定会做到的。", 1);
	Say("张琳心：独孤哥哥……", 26);
	FadeOut();
    ShowNpc("张琳心", 1);
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf"); 
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
    FadeIn();	
		
	Say("独孤剑：琳儿，我们将世伯入土为安吧。", 1);
	SetNpcDir("张琳心", 5);
	Say("张琳心：爹……", 26);
	
	//埋葬张风
	
	FadeOut();
	SetNpcKind("张琳心", 3);  //恢复同伴
	LoadNpc("map034.npc");
	LoadObj("map034.obj");
	SetPlayerPos(5, 8);
	SetPlayerDir(1);
	SetNpcKind("张琳心", 1);   //取消同伴
	SetNpcPos("张琳心", 4, 9);	
	SetNpcDir("张琳心", 5);
	FadeIn();
	
	Say("独孤剑：琳儿，没想到你爹和我爹之间竟有这样一段故事，他们才是真朋友、真英雄！一个想朋友杀，一个要杀朋友，天底下的义气还有比这更义气的吗？", 1);
	Say("张琳心：独孤哥哥……", 26);
	Say("独孤剑：琳儿，人活一辈子，总逃不过个死字，求的不过是个心安理得，你爹临死时，总算解开了一辈子的心结，对他未尝不是件好事，你应该为你爹高兴才是。", 1);
	Say("张琳心：嗯……", 26);
	SetNpcDir("张琳心", 3);
	Say("张琳心：爹……", 26);
	Sleep(1000);
	Say("独孤剑：琳儿，别哭了，你爹的仇，既是家恨，也是国仇，总有一天，我们会讨回这笔血帐！", 1);
	SetPlayerDir(3);
	Say("独孤剑：世伯，你放心！剑儿一定谨记你的遗志，赴汤蹈火，在所不辞。", 1);
	Say("张琳心：爹爹，我会将真相告诉哥哥，他一定会谅解爹您的……", 26);
	Watch("独孤剑", "张琳心", 0);
	Say("独孤剑：琳儿，别伤心了，我相信你哥哥一定会原谅你爹的！", 1);
	Say("张琳心：独孤哥哥！……", 26);
	ShowNpc("张琳心", 0);
	SetNpcActionFile("独孤剑", 0, "mpc406_2.asf");
	SetNpcActionFile("独孤剑", 1, "mpc406_2.asf");
	NpcSpecialAction("独孤剑", "mpc406_1.asf");
	Sleep(2500);
	Say("张琳心：独孤哥哥，我现在已经没有了爹，你……不要离开我，好么？", 24);
	Say("独孤剑：琳儿，只要你愿意，我会一直陪在你身边，永远也不离开你。", 2);
	Say("张琳心：独孤哥哥！", 22);
	Say("独孤剑：琳儿！", 4);
	FadeOut();
    ShowNpc("张琳心", 1);
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf"); 
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
    FadeIn();
		
	Sleep(1000);
	Say("独孤剑：琳儿，时间不早了，我们赶紧去小渔村找小叫化和段姑娘吧。", 1);
	Say("张琳心：好。", 21);
	SetNpcDir("张琳心", 3);
